import React from "react";
import { AbsoluteFill, Html5Audio, Sequence, staticFile } from "remotion";
import { HEIGHT, SCENE_PAD, SceneKey, WIDTH, getAudio, getSegments } from "../constants";
import { Background } from "./Background";
import { Subtitles } from "./Subtitles";

// Every scene: persistent background, a 1920×1080 SVG canvas for the
// illustration, subtitles, and the scene's narration once it has been
// generated by scripts/generate-tts.mjs.
export const SceneShell: React.FC<{
  sceneKey: SceneKey;
  tint?: string;
  tintOpacity?: number;
  children: React.ReactNode;
}> = ({ sceneKey, tint, tintOpacity, children }) => {
  const audio = getAudio(sceneKey);
  return (
    <AbsoluteFill>
      <Background tint={tint} tintOpacity={tintOpacity} />
      <AbsoluteFill>
        <svg width={WIDTH} height={HEIGHT} viewBox={`0 0 ${WIDTH} ${HEIGHT}`}>
          {children}
        </svg>
      </AbsoluteFill>
      <Subtitles segments={getSegments(sceneKey)} />
      {audio ? (
        <Sequence from={SCENE_PAD} name="Narración">
          <Html5Audio src={staticFile(audio.file)} />
        </Sequence>
      ) : null}
    </AbsoluteFill>
  );
};
